-- Batch 01: reviewed internal project material pages, immutable source hashes.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL application_name='colliers_ai_backfill_20261125_v5';
DO $fill$
DECLARE r record; n int:=0; old_count int; changed int; ev uuid; now_ts timestamptz; read_value jsonb; source_row jsonb; sub_batch int:=1; expected_before int:=0; expected_added int:=22;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ai_building_field_backfill_20261125_v5_100'));
 SELECT count(*) INTO old_count FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v5_100';
 IF old_count<>expected_before OR old_count+expected_added>100 THEN RAISE EXCEPTION 'batch sequence guard: %',old_count; END IF;
 -- Serialize the brief data transaction against other writes, not normal reads.
 LOCK TABLE public.buildings,public.building_brochure_data,public.building_data_field_provenance IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE public.project_material_library,public.project_material_library_pages IN SHARE MODE;
 FOR r IN
 WITH specs AS (SELECT * FROM jsonb_to_recordset($spec$[{"lib":"62e1d8fb-3717-502d-b3b2-5318dce6fe48","pg":6,"hash":"0ffd418349cf036d62733073bdb0ba446d3e79602753c2e76b8e589860c421af","name":"华贸中心三座","f":"building_height","type":"numeric","unit":"m","pat":"T3：([0-9]+)m","note":"T3单塔高度"},{"lib":"62e1d8fb-3717-502d-b3b2-5318dce6fe48","pg":6,"hash":"0ffd418349cf036d62733073bdb0ba446d3e79602753c2e76b8e589860c421af","name":"华贸中心三座","f":"depth","type":"numeric","unit":"m","pat":"进深和柱距[[:space:]]+([0-9.]+)m/[0-9.]+m","note":"已审阅项目历史技术参数，非本次现场测量"},{"lib":"62e1d8fb-3717-502d-b3b2-5318dce6fe48","pg":6,"hash":"0ffd418349cf036d62733073bdb0ba446d3e79602753c2e76b8e589860c421af","name":"华贸中心三座","f":"column_spacing","type":"numeric","unit":"m","pat":"进深和柱距[[:space:]]+[0-9.]+m/([0-9.]+)m","note":"已审阅项目历史技术参数，非本次现场测量"},{"lib":"62e1d8fb-3717-502d-b3b2-5318dce6fe48","pg":6,"hash":"0ffd418349cf036d62733073bdb0ba446d3e79602753c2e76b8e589860c421af","name":"华贸中心三座","f":"facade_type","type":"text","unit":"configuration","pat":"建筑外墙[[:space:]]+(LOW-E 低反射中空玻璃幕墙)","note":"已审阅项目历史技术参数，非本次现场测量"},{"lib":"62e1d8fb-3717-502d-b3b2-5318dce6fe48","pg":6,"hash":"0ffd418349cf036d62733073bdb0ba446d3e79602753c2e76b8e589860c421af","name":"华贸中心三座","f":"hvac_pm25_purification","type":"boolean","unit":"boolean","pat":"(PM2[.]5净化器)","note":"已审阅项目历史技术参数，非本次现场测量"},{"lib":"62e1d8fb-3717-502d-b3b2-5318dce6fe48","pg":6,"hash":"0ffd418349cf036d62733073bdb0ba446d3e79602753c2e76b8e589860c421af","name":"华贸中心三座","f":"floor_load_office","type":"integer","unit":"kg/m2","pat":"楼板荷载[[:space:]]+([0-9]+)kg/㎡，局部承重","note":"普通楼板负荷，非局部最大值"},{"lib":"c8f1eef2-1425-5ef3-b97d-7e9982415b36","pg":63,"hash":"ced70000a146724fa40f4da9da668fdbdd75e994e30e7cb7c5d00b1d5b9489c3","name":"友邦金融中心","f":"facade_type","type":"text","unit":"configuration","pat":"幕墙[[:space:]]+(石材[+]Low-e钢化中空玻璃)","note":"已审阅项目历史技术参数，非本次现场测量"},{"lib":"c8f1eef2-1425-5ef3-b97d-7e9982415b36","pg":63,"hash":"ced70000a146724fa40f4da9da668fdbdd75e994e30e7cb7c5d00b1d5b9489c3","name":"友邦金融中心","f":"hvac_cooling_water_24h","type":"boolean","unit":"boolean","pat":"(提供24小时冷却水供租户机房使用)","note":"已审阅项目历史技术参数，非本次现场测量"},{"lib":"f1fe887c-539b-5846-8e48-811d16702a8c","pg":13,"hash":"32e53f1d0d1838ad3a7e11eac9e6376e24819b3e2dc050758ee76dd5547ff67a","name":"丰融国际大厦","f":"hvac_pm25_purification","type":"boolean","unit":"boolean","pat":"(PM2[.]5三重过滤)","note":"已审阅项目历史技术参数，非本次现场测量"},{"lib":"f1fe887c-539b-5846-8e48-811d16702a8c","pg":13,"hash":"32e53f1d0d1838ad3a7e11eac9e6376e24819b3e2dc050758ee76dd5547ff67a","name":"丰融国际大厦","f":"power_backup_generator","type":"text","unit":"configuration","pat":"(2台[(]625kw/台[)])","note":"原页紧急供电机组列，未推断燃料"},{"lib":"295d6495-a0d5-536e-b38e-96ece05a5d73","pg":70,"hash":"31db5903778e573b5c4ecbf61382c632b9910bbba3674e9fb0ce3532bfd69876","name":"嘉铭奥森产业园","f":"hvac_pm25_purification","type":"boolean","unit":"boolean","pat":"(PM2[.]5净化装置)","note":"已审阅项目历史技术参数，非本次现场测量"},{"lib":"696b57ef-e58d-556b-aa27-83cad79d39cf","pg":18,"hash":"536524b0da77164aaebd5e2cfe4d75afdf1b19c9ea9035e5187b00556e6148ea","name":"国航大厦","f":"depth","type":"numeric","unit":"m","pat":"标准层层高3[.]2米，进深达([0-9]+)米","note":"标准层进深，非特定单元最大值"},{"lib":"14e25a2b-4e42-5152-a544-fde121af679d","pg":22,"hash":"8393678d39d1fd7bb83334322865f149971325b381a71a0193dffcc1798e29fd","name":"泰康金融大厦","f":"column_free","type":"boolean","unit":"boolean","pat":"(中央核心筒，无柱结构)","note":"22—24页多个办公层一致"},{"lib":"14e25a2b-4e42-5152-a544-fde121af679d","pg":22,"hash":"8393678d39d1fd7bb83334322865f149971325b381a71a0193dffcc1798e29fd","name":"泰康金融大厦","f":"power_system","type":"text","unit":"configuration","pat":"供电[[:space:]]+(双路供电)","note":"22—24页多个办公层一致"},{"lib":"47d9ac36-5222-5dd7-afc6-9cadac60e36f","pg":41,"hash":"e182dd36832f536a16ba3a5efaefa9d48f57756c2ac0bc9e92c6e72c35816a80","name":"玖安广场","f":"floor_load_office","type":"integer","unit":"kg/m2","pat":"楼板承重[[:space:]]+([0-9]+)公斤/平方米","note":"已审阅项目历史技术参数，非本次现场测量"},{"lib":"47d9ac36-5222-5dd7-afc6-9cadac60e36f","pg":41,"hash":"e182dd36832f536a16ba3a5efaefa9d48f57756c2ac0bc9e92c6e72c35816a80","name":"玖安广场","f":"efficiency_rate","type":"numeric","unit":"percent","pat":"大厦使用率[[:space:]]*[(]%[)][[:space:]]+([0-9]+)%","note":"已审阅项目历史技术参数，非本次现场测量"},{"lib":"47d9ac36-5222-5dd7-afc6-9cadac60e36f","pg":41,"hash":"e182dd36832f536a16ba3a5efaefa9d48f57756c2ac0bc9e92c6e72c35816a80","name":"玖安广场","f":"delivery_standard","type":"text","unit":"configuration","pat":"交付状况[[:space:]]+(吊顶、白墙、网络地板、电动窗帘)","note":"历史标准交付，非当前单元状态"}]$spec$::jsonb) v(lib uuid,pg int,hash text,name text,f text,type text,unit text,pat text,note text)), c AS (
 SELECT b.id bid,b.name,d.id target_id,v.f field_name,CASE v.type WHEN 'numeric' THEN to_jsonb(m.val::numeric) WHEN 'integer' THEN to_jsonb(m.val::integer) WHEN 'boolean' THEN to_jsonb(true) ELSE to_jsonb(trim(regexp_replace(m.val,'[[:space:]]+',' ','g'))) END new_value,v.type value_type,'project_material_library' source_table,l.id source_id,'page:'||v.pg source_field,'internal_archived_page' source_kind,v.unit,v.note||'; page_sha256='||v.hash note
 FROM specs v JOIN project_material_library l ON l.id=v.lib JOIN project_material_library_pages p ON p.extraction_id=l.id AND p.page_number=v.pg AND p.content_sha256=v.hash JOIN buildings b ON b.name=v.name JOIN building_brochure_data d ON d.building_id=b.id CROSS JOIN LATERAL (SELECT (regexp_match(p.content->>'native_text',v.pat))[1] val) m
 WHERE l.review_state IN ('reviewed','needs_association') AND EXISTS(SELECT 1 FROM jsonb_array_elements(l.payload->'sections') AS sections(sec) CROSS JOIN LATERAL jsonb_array_elements(case when jsonb_typeof(sec->'facts')='array' then sec->'facts' else '[]'::jsonb end) AS facts(fact) CROSS JOIN LATERAL regexp_matches(fact->>'source_ref','第([0-9]+(?:、[0-9]+)*)页','g') z WHERE sec->>'association_status'='confirmed' AND sec->'candidate_building_ids' ? b.id::text AND jsonb_array_length(sec->'candidate_building_ids')=1 AND v.pg::text=ANY(string_to_array(z[1],'、')))
 AND b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND b.project_type='stock' AND b.merged_into_id IS NULL AND (SELECT count(*) FROM building_brochure_data y WHERE y.building_id=b.id)=1 AND to_jsonb(d)->v.f='null'::jsonb AND m.val IS NOT NULL
 UNION ALL SELECT b.id,b.name,d.id,'power_source',to_jsonb('市政双路供电'::text),'text','building_brochure_data',d.id,'power_system','internal_field_extraction','configuration_text','明确市政电源配置；源字段原样提取；保留原历史或规划口径'
 FROM buildings b JOIN building_brochure_data d ON d.building_id=b.id WHERE b.name IN ('Z3东环捌号','中海商务中心（四川大厦）','北投投资大厦','霄云路33号') AND b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND b.merged_into_id IS NULL AND d.power_source IS NULL AND d.power_system LIKE '市政双路供电%' AND (SELECT count(*) FROM building_brochure_data y WHERE y.building_id=b.id)=1
 UNION ALL SELECT b.id,b.name,d.id,'power_backup_generator',to_jsonb((regexp_match(d.power_system,'(大厦应急柴油发电机组[0-9]+台，其中[0-9]+台为租户预留)'))[1]),'text','building_brochure_data',d.id,'power_system','internal_field_extraction','configuration_text','未入市项目既有设计参数；保留预留台数，不声称已安装'
 FROM buildings b JOIN building_brochure_data d ON d.building_id=b.id WHERE b.name='Z3东环捌号' AND b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND b.merged_into_id IS NULL AND b.project_type='future' AND b.is_entered_market=false AND d.power_backup_generator IS NULL AND d.power_system ~ '大厦应急柴油发电机组[0-9]+台，其中[0-9]+台为租户预留'
) SELECT c.* FROM c WHERE new_value IS NOT NULL AND NOT EXISTS(SELECT 1 FROM building_data_field_provenance p WHERE p.building_id=c.bid AND p.target_table='building_brochure_data' AND p.field_name=c.field_name) AND NOT EXISTS(SELECT 1 FROM audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.target_table='building_brochure_data' AND a.target_id=c.target_id::text AND (a.details->>'field_name'=c.field_name OR a.new_values ? c.field_name)) ORDER BY target_id,field_name
 LOOP
  IF r.new_value IS NULL OR r.new_value='null'::jsonb OR r.value_type NOT IN ('text','integer','numeric','boolean','date') THEN RAISE EXCEPTION 'invalid candidate'; END IF;
  ev:=gen_random_uuid(); now_ts:=clock_timestamp();
  EXECUTE format('UPDATE public.building_brochure_data SET %I=($2#>>''{}'')::%s WHERE id=$1 AND building_id=$3 AND %I IS NULL',r.field_name,r.value_type,r.field_name) USING r.target_id,r.new_value,r.bid;
  GET DIAGNOSTICS changed=ROW_COUNT;
  IF changed<>1 THEN RAISE EXCEPTION 'null protection failed'; END IF;
  INSERT INTO public.building_data_field_provenance(building_id,brochure_data_id,target_table,field_name,field_value,source_type,source_tier,source_name,source_retrieved_at,value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
  VALUES(r.bid,r.target_id,'building_brochure_data',r.field_name,r.new_value,CASE WHEN r.source_kind='internal_archived_page' THEN 'brochure' ELSE 'other' END,CASE WHEN r.source_kind='internal_archived_page' THEN 'secondary' ELSE 'legacy_unknown' END,CASE WHEN r.source_kind='internal_archived_page' THEN '高力国际已审阅历史项目资料' ELSE '高力国际内部已有业务记录' END,now_ts,now_ts,'legacy_backfill',ev,'batch_ref=ai_building_field_backfill_20261125_v5_100; source_table='||r.source_table||'; source_record_id='||r.source_id||'; source_field='||r.source_field||'; unit='||r.unit||'; '||r.note||'; AI-assisted',true);
  INSERT INTO public.audit_logs(id,user_id,action_type,details,request_source,module,target_table,target_id,target_name,old_values,new_values,event_id,occurred_at,actor_kind,actor_name)
  VALUES(nextval('public.audit_logs_id_seq'),'codex','AI_FIELD_FILL',jsonb_build_object('batch_ref','ai_building_field_backfill_20261125_v5_100','sub_batch',sub_batch,'building_id',r.bid,'field_name',r.field_name,'source_table',r.source_table,'source_record_id',r.source_id,'source_field',r.source_field,'source_kind',r.source_kind,'unit',r.unit,'verification_status','legacy_backfill','evidence_group_id',ev,'ai_assisted',true,'reversible',true),'codex_mcp','building_brochure_data','building_brochure_data',r.target_id::text,r.name,jsonb_build_object(r.field_name,NULL),jsonb_build_object(r.field_name,r.new_value),'ai_field_fill:'||ev::text,now_ts,'tool','Codex（工具执行）');
  EXECUTE format('SELECT to_jsonb(%I) FROM public.building_brochure_data WHERE id=$1',r.field_name) INTO read_value USING r.target_id;
  IF read_value IS DISTINCT FROM r.new_value OR NOT EXISTS(SELECT 1 FROM public.building_data_field_provenance p JOIN public.audit_logs a ON a.event_id='ai_field_fill:'||ev::text WHERE p.evidence_group_id=ev AND p.is_current AND p.field_value=read_value AND a.new_values->r.field_name=p.field_value AND a.old_values->r.field_name='null'::jsonb) THEN RAISE EXCEPTION 'readback failed'; END IF;
  n:=n+1;
 END LOOP;
 IF n<>expected_added THEN RAISE EXCEPTION 'expected % qualifying fields, got %',expected_added,n; END IF;
END $fill$;
SELECT count(*) cumulative,count(distinct (target_table,target_id,details->>'field_name')) unique_fields FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v5_100';
COMMIT;